import { saveApplication, saveContactMessage } from "./storage.min.js?v=20260724-2";
function getErrorElement(input) {
const field = input.closest(".field");
return field ? field.querySelector(".field-error") : null;
}
function setError(input, message) {
const error = getErrorElement(input);
input.setAttribute("aria-invalid", "true");
if (error) {
error.textContent = message;
}
}
function clearError(input) {
const error = getErrorElement(input);
input.removeAttribute("aria-invalid");
if (error) {
error.textContent = "";
}
}
function isValidEmail(value) {
return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}
function phoneDigits(value) {
return value.replace(/\D/g, "");
}
function validateRequired(input, message) {
if (!input.value.trim()) {
setError(input, message);
return false;
}
clearError(input);
return true;
}
function focusFirstError(form) {
const invalid = form.querySelector("[aria-invalid='true']");
if (invalid) {
invalid.focus();
}
}
function showSuccess(root, message) {
const success = root.querySelector("[data-form-success]");
if (success) {
success.hidden = false;
success.textContent = message;
success.focus();
}
}
function hideSuccess(root) {
const success = root.querySelector("[data-form-success]");
if (success) {
success.hidden = true;
success.textContent = "";
}
}
function validateApplicationForm(form) {
let valid = true;
const fullName = form.elements.fullName;
const email = form.elements.email;
const phone = form.elements.phone;
const qualification = form.elements.qualification;
const experience = form.elements.experience;
const resume = form.elements.resume;
const coverLetter = form.elements.coverLetter;
valid = validateRequired(fullName, "Enter your full name.") && valid;
if (!email.value.trim()) {
setError(email, "Enter your email address.");
valid = false;
} else if (!isValidEmail(email.value.trim())) {
setError(email, "Enter a valid email address.");
valid = false;
} else {
clearError(email);
}
const digits = phoneDigits(phone.value);
if (!phone.value.trim()) {
setError(phone, "Enter your phone number.");
valid = false;
} else if (digits.length < 10 || digits.length > 15) {
setError(phone, "Enter a valid phone number with 10 to 15 digits.");
valid = false;
} else {
clearError(phone);
}
valid = validateRequired(qualification, "Select your highest qualification.") && valid;
const years = Number(experience.value);
if (experience.value === "") {
setError(experience, "Enter your years of experience.");
valid = false;
} else if (Number.isNaN(years) || years < 0 || years > 50) {
setError(experience, "Experience must be between 0 and 50 years.");
valid = false;
} else {
clearError(experience);
}
const selectedFile = resume.files && resume.files[0];
if (!selectedFile) {
setError(resume, "Attach a resume file.");
valid = false;
} else if (!/\.(pdf|doc|docx)$/i.test(selectedFile.name)) {
setError(resume, "Use a PDF, DOC, or DOCX resume.");
valid = false;
} else {
clearError(resume);
}
if (!coverLetter.value.trim()) {
setError(coverLetter, "Write a short cover letter.");
valid = false;
} else if (coverLetter.value.trim().length < 40) {
setError(coverLetter, "Cover letter should be at least 40 characters.");
valid = false;
} else {
clearError(coverLetter);
}
return valid;
}
export function setupApplyForm(root, job) {
const form = root.querySelector("[data-apply-form]");
const resumeInput = root.querySelector('input[name="resume"]');
const resumeName = root.querySelector("[data-resume-name]");
if (!form) {
return;
}
root.addEventListener("input", (event) => {
if (event.target.matches("input, textarea, select")) {
clearError(event.target);
hideSuccess(root);
}
});
if (resumeInput && resumeName) {
resumeInput.addEventListener("change", () => {
resumeName.textContent = resumeInput.files && resumeInput.files[0] ? resumeInput.files[0].name : "No file selected";
clearError(resumeInput);
hideSuccess(root);
});
}
form.addEventListener("submit", (event) => {
event.preventDefault();
if (!validateApplicationForm(form)) {
focusFirstError(form);
return;
}
const formData = new FormData(form);
const record = saveApplication({
jobId: job ? job.id : "",
jobTitle: job ? job.title : "General application",
company: job ? job.company : "",
fullName: formData.get("fullName").trim(),
email: formData.get("email").trim(),
phone: formData.get("phone").trim(),
qualification: formData.get("qualification"),
experience: formData.get("experience"),
resumeName: resumeInput.files[0].name,
coverLetter: formData.get("coverLetter").trim()
});
form.reset();
if (resumeName) {
resumeName.textContent = "No file selected";
}
showSuccess(root, `Application ${record.id.slice(0, 18)} submitted successfully for ${record.jobTitle}.`);
});
}
function validateContactForm(form) {
let valid = true;
const name = form.elements.name;
const email = form.elements.email;
const subject = form.elements.subject;
const message = form.elements.message;
valid = validateRequired(name, "Enter your name.") && valid;
if (!email.value.trim()) {
setError(email, "Enter your email address.");
valid = false;
} else if (!isValidEmail(email.value.trim())) {
setError(email, "Enter a valid email address.");
valid = false;
} else {
clearError(email);
}
if (!subject.value.trim()) {
setError(subject, "Enter a subject.");
valid = false;
} else if (subject.value.trim().length < 4) {
setError(subject, "Subject should be at least 4 characters.");
valid = false;
} else {
clearError(subject);
}
if (!message.value.trim()) {
setError(message, "Enter your message.");
valid = false;
} else if (message.value.trim().length < 20) {
setError(message, "Message should be at least 20 characters.");
valid = false;
} else {
clearError(message);
}
return valid;
}
export function setupContactForm(root) {
const form = root.querySelector("[data-contact-form]");
if (!form) {
return;
}
root.addEventListener("input", (event) => {
if (event.target.matches("input, textarea")) {
clearError(event.target);
hideSuccess(root);
}
});
form.addEventListener("submit", (event) => {
event.preventDefault();
if (!validateContactForm(form)) {
focusFirstError(form);
return;
}
const formData = new FormData(form);
saveContactMessage({
name: formData.get("name").trim(),
email: formData.get("email").trim(),
subject: formData.get("subject").trim(),
message: formData.get("message").trim()
});
form.reset();
showSuccess(root, "Thanks. Your message has been recorded and the CareerConnect team will respond shortly.");
});
}